cd /tmp/dev && cat > bench6.py <<'PYEOF'
import sys, time, random
sys.path.insert(0,'/workspace/deps')
import networkx as nx
random.seed(1)
NR=4096; NO=8192; PAIRS=262144
G=nx.DiGraph()
S='S'; T='T'
RQ=[('rq',i) for i in range(4)]
OQ=[('oq',i) for i in range(4)]
for i,n in enumerate(RQ):
    if i==0: G.add_edge(S,n,capacity=4096,weight=0)
    else: G.add_edge(RQ[i-1],n,capacity=4096,weight=0)
for i,n in enumerate(OQ):
    if i==0: G.add_edge(n,T,capacity=4096,weight=0)
    else: G.add_edge(OQ[i],OQ[i-1],capacity=4096,weight=0)
requests=[('r',i) for i in range(NR)]
for i,r in enumerate(requests): G.add_edge(RQ[i%4], r, capacity=1, weight=0)
offers=[('o',i) for i in range(NO)]
for i,o in enumerate(offers): G.add_edge(o, OQ[i%4], capacity=1, weight=0)
pairs=set()
while len(pairs)<PAIRS: pairs.add((random.randrange(NR), random.randrange(NO)))
costs=[random.randrange(10**9) for _ in range(NO)]
for a,b in pairs: G.add_edge(requests[a], offers[b], capacity=1, weight=costs[b])
print('nodes',G.number_of_nodes(),'edges',G.number_of_edges(),flush=True)
t=time.time(); mf=nx.maximum_flow_value(G,S,T); print('maxflow',mf,time.time()-t,flush=True)
H=nx.DiGraph(G)
H.add_node(S,demand=-mf); H.add_node(T,demand=mf)
t=time.time()
cost,fd=nx.network_simplex(H)
print('simplex',cost,time.time()-t,flush=True)
cnt=0;c2=0
for u in requests:
    for v,f in fd[u].items():
        if f: cnt+=1; c2+=costs[v[1]]
print('assignments',cnt,'offercost',c2,flush=True)
PYEOF
